export function verifyDiagnostics(text:string,expectedSha:string,expectedHead:string,expectedRequests:number){
 check(sha(text)===expectedSha,'Exact diagnostic hash');const es=readM78Continuation4Diagnostics(text),first=es[0]!,last=es.at(-1)!;check(first.kind==='phase_started'&&same(first.data.priorFailure,{...M78_CONTINUATION4_PRIOR_FAILURE,main:M78_CONTINUATION4_PATHS.failedMain,diagnostics:M78_CONTINUATION4_PATHS.failedDiagnostics,review:M78_CONTINUATION4_PATHS.failedReview})&&same(first.data.transport,{runtime:'bun-fetch',pooling:'disabled',keepalive:false,retries:0})&&same(first.data.interruption,M78_CONTINUATION3_INTERRUPTION)&&same(first.data.disposition,DISPOSITION_PIN)&&first.data.journal==='.superpowers/m78-hosted-continuation4.jsonl','Exact diagnostic parent');check(last.sha256===expectedHead&&last.kind==='phase_finished'&&last.data.status==='passed'&&last.data.diagnosticsHealthy===true&&last.data.paused===false&&last.data.applicationPostRequests===0&&last.data.allCreatedAuthSessionsClosed===true,'Diagnostic passed closure');
 const requests=new Map<number,any>();let ordinal=0,lastTime=0;for(const e of es){const timestamp=Date.parse(e.createdAt);check(Number.isFinite(timestamp)&&timestamp>=lastTime&&e.mode==='baseline','Diagnostic chronology/mode');lastTime=timestamp;if(e.kind==='request_intent'){check(e.data.ordinal===++ordinal&&['GET','POST'].includes(e.data.method),'Diagnostic request order');check(e.data.method!=='POST'||['auth:/auth/v1/token','auth:/auth/v1/logout'].includes(e.data.route),'No diagnostic application POST');requests.set(ordinal,{...e.data,outcome:null})}else if(e.kind==='response_headers'){const r=requests.get(e.data.ordinal);check(r&&r.outcome===null&&Number.isInteger(e.data.status)&&[200,204,401,403].includes(e.data.status)&&Number.isFinite(e.data.elapsedMs)&&e.data.elapsedMs>=0,'Paired successful/expected-denial headers');if(r.route==='auth:/auth/v1/token')check(e.data.status===200,'Login headers');if(r.route==='auth:/auth/v1/logout')check(e.data.status===204,'Logout headers');r.outcome=e.data}else check((e===first&&e.kind==='phase_started')||(e===last&&e.kind==='phase_finished'),'No errors or extra diagnostic phase')}
 check(requests.size===expectedRequests&&[...requests.values()].every(r=>r.outcome!==null),'Complete paired requests');check([...requests.values()].filter(r=>r.route==='auth:/auth/v1/token').length===8&&[...requests.values()].filter(r=>r.route==='auth:/auth/v1/logout').length===8,'All main and legacy diagnostic sessions');return {events:es.length,requests:requests.size,startedAt:first.createdAt,finishedAt:last.createdAt};
}
